challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("jobs=(d2,p100),(d1,p19),(d2,p27),(d1,p25),(d3,p15)","142"),
        ("jobs=(d1,p5),(d1,p10)","10"),
        ("jobs=(d1,p10),(d2,p20)","30"),
        ("jobs=(d1,p3),(d1,p9),(d1,p6)","9"),
        ("jobs=(d3,p5),(d1,p7),(d2,p8)","20"),
        ("  \njobs=(d2,p100),(d1,p19),(d2,p27),(d1,p25),(d3,p15)\n  ","142"),
        ("\njobs=(d3,p5),(d1,p7),(d2,p8)\n","20")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS deadline-scheduling");
}
